input.sparql:
SELECT ?eq ?name ?sensor ?ts WHERE {
  ?sensor a brick:Power .
  ?sensor brick:hasParentEquipment ?eq .
  ?sensor ref:hasTimeseriesId ?ts .
  OPTIONAL { ?eq rdfs:label ?name . }
}

SELECT ?sensor ?eq ?name ?ts WHERE {
  ?sensor a brick:Power .
  ?sensor brick:isPointOf ?eq .
  OPTIONAL { ?eq rdfs:label ?name . }
  ?sensor ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT DISTINCT ?eq ?name WHERE {
  ?s brick:isPointOf ?eq .
  ?s a ?sc .
  FILTER (?sc IN (brick:Power_Sensor, brick:Electric_Power_Sensor))
  OPTIONAL { ?eq rdfs:label ?name . }
}

SELECT ?eq ?name WHERE {
  ?eq a ?t .
  FILTER (CONTAINS(STR(?t), "Equipment") )
  OPTIONAL { ?eq rdfs:label ?name . }
}

SELECT ?eq ?label ?type WHERE {
  ?eq a brick:Equipment .
  OPTIONAL { ?eq rdfs:label ?label . }
  } LIMIT 50

SELECT ?eq ?label ?ts WHERE {
  ?s brick:isPointOf ?eq .
  ?s a ?sc .
  FILTER (?sc IN (brick:Power_Sensor, brick:Electric_Power_Sensor))
  ?s ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  OPTIONAL { ?eq rdfs:label ?label . }
  FILTER (!CONTAINS(STR(?eq), "Zone"))
}

